const money=(value:number)=>new Intl.NumberFormat('fa-IR').format(value);
</script>
<template><Head title="پرداخت شهریه"/><main class="min-h-screen bg-[#f4f3ef] p-4 text-[#102236]" dir="rtl"><div class="mx-auto max-w-lg pt-8 md:pt-16"><header class="mb-5 flex items-center gap-3"><div class="brand-mark"><Volleyball :size="22"/></div><div><h1 class="text-base font-black">{{invoice.club}}</h1><p class="mt-1 text-[9px] text-[#7b878f]">درگاه پرداخت امن شهریه</p></div></header><section class="panel-flat overflow-hidden"><div class="bg-[#0b2a44] p-6 text-white"><p class="text-[9px] font-black text-[#f29a66]">صورتحساب ورزشکار</p><h2 class="mt-2 text-xl font-black">{{invoice.athlete}}</h2><p class="mt-2 text-[10px] text-[#b4c4cf]">{{invoice.title}}</p></div><div class="p-6"><div v-if="successMessage||invoice.is_paid" class="mb-5 flex items-center gap-2 border border-[#bcd9ca] bg-[#edf7f1] p-4 text-[11px] font-black text-[#236b54]"><CheckCircle2 :size="18"/>{{successMessage||'این صورتحساب با موفقیت تسویه شده است.'}}</div><div v-if="errorMessage" class="mb-5 flex items-center gap-2 border border-[#e5bdb5] bg-[#fbefec] p-4 text-[11px] font-black text-[#a74331]"><AlertCircle :size="18"/>{{errorMessage}}</div><div class="space-y-4"><div class="flex justify-between border-b border-[#e2e5e6] pb-4 text-[10px]"><span class="text-[#7c8991]">مبلغ صورتحساب</span><strong>{{money(invoice.amount)}} تومان</strong></div><div class="flex justify-between border-b border-[#e2e5e6] pb-4 text-[10px]"><span class="text-[#7c8991]">پرداخت قبلی</span><strong>{{money(invoice.paid)}} تومان</strong></div><div class="flex items-end justify-between bg-[#faf5ef] p-4"><span class="text-[10px] font-bold">مبلغ قابل پرداخت</span><strong class="text-xl font-black text-[#d86529]">{{money(invoice.outstanding)}} <small class="text-[8px]">تومان</small></strong></div></div><form v-if="!invoice.is_paid" class="mt-6" @submit.prevent="form.post(`/pay/${invoice.token}`)"><button class="primary-sport-button w-full py-4" :disabled="form.processing"><CreditCard :size="18"/>{{form.processing?'در حال انتقال